const fanChatCache = new Map<string, { stamp: string; row: any }>();

export function chats(includeOwned = true) {
  let files: string[] = [];
  try { files = fs.readdirSync(girlDataDir()).filter((f) => f.endsWith(".json") && !f.startsWith("_")); } catch {}
  return files.map((f) => {
    const id = f.replace(/\.json$/, ""), p = path.join(girlDataDir(), f);
    // O18: one unreadable chat file is shown as unreadable, never allowed to blank the whole list.
    try {
      let stamp = "";
      if (!includeOwned) {
        try {
          const stat = fs.statSync(p);
          stamp = [stat.dev, stat.ino, stat.size, stat.mtimeMs, stat.ctimeMs].join(":");
          const cached = fanChatCache.get(p);
          if (cached?.stamp === stamp) return cached.row;
        } catch { /* retain the existing unreadable-file behavior below */ }
      }
      const c = JSON.parse(fs.readFileSync(p, "utf8"));
      if (!c || typeof c !== "object" || Array.isArray(c)) throw new Error("not a chat object");
      const row = { id, ageConfirmed: !!c.ageConfirmed, messages: c.history?.length ?? 0, sent: c.sent?.length ?? 0,
        updated: fs.statSync(p).mtime.toISOString(), history: c.history ?? [], sentKeys: c.sent ?? [], who: c.who ?? null, bcid: c.bcid ?? null, owned: includeOwned ? [...ownedKeys(id)] : [], unreadable: null as string | null };
      if (!includeOwned && stamp) {
        const stat = fs.statSync(p);
        const after = [stat.dev, stat.ino, stat.size, stat.mtimeMs, stat.ctimeMs].join(":");
        if (after === stamp) {
          if (fanChatCache.size > 100_000) fanChatCache.clear();
          // Fans need metadata only. Do not retain chat bodies or ownership.
          fanChatCache.set(p, { stamp, row: { ...row, history: [], sentKeys: [], owned: [] } });
        } else fanChatCache.delete(p);
      }
      return row;
    } catch (e) {
      let updated = new Date(0).toISOString();
      try { updated = fs.statSync(p).mtime.toISOString(); } catch {}
      return { id, ageConfirmed: false, messages: 0, sent: 0, updated, history: [] as any[], sentKeys: [] as any[], who: null, bcid: null, owned: [] as string[], unreadable: String((e as any)?.message ?? e).slice(0, 160) };
    }
  }).sort((a, b) => (a.updated < b.updated ? 1 : -1));
}
